import {useState, useEffect} from 'react';
import {ApiProfessor} from "../api";

const useProfessor = (professor) => {
    const [state, setState] = useState(null);
    useEffect(() => {
        setProfessor();
    },[professor]);

    const setProfessor = async () => {
        const professorEndpoint = professor ? professor : undefined;
        if(professorEndpoint){
            const professor = await ApiProfessor(professorEndpoint);
            setState(professor);
        }
    };
    return [state, setProfessor];
};

export default useProfessor;
